BEGIN;
PRAGMA writable_schema = on;
PRAGMA encoding = 'UTF-8';
PRAGMA page_size = '4096';
PRAGMA auto_vacuum = '0';
PRAGMA user_version = '0';
PRAGMA application_id = '0';
CREATE TABLE sqlite_sequence(name,seq);
CREATE TABLE tasks (
    id                   TEXT PRIMARY KEY,
    title                TEXT NOT NULL,
    body                 TEXT,
    assignee             TEXT,
    status               TEXT NOT NULL,
    priority             INTEGER DEFAULT 0,
    created_by           TEXT,
    created_at           INTEGER NOT NULL,
    started_at           INTEGER,
    completed_at         INTEGER,
    workspace_kind       TEXT NOT NULL DEFAULT 'scratch',
    workspace_path       TEXT,
    branch_name          TEXT,
    claim_lock           TEXT,
    claim_expires        INTEGER,
    tenant               TEXT,
    result               TEXT,
    idempotency_key      TEXT,
    -- Unified consecutive-failure counter. Incremented on spawn
    -- failure, timeout, or crash; reset only on successful completion.
    -- The circuit breaker in _record_task_failure trips when this
    -- exceeds DEFAULT_FAILURE_LIMIT consecutive non-successes.
    consecutive_failures INTEGER NOT NULL DEFAULT 0,
    worker_pid           INTEGER,
    -- Short excerpt of the most recent failure's error text.
    last_failure_error   TEXT,
    max_runtime_seconds  INTEGER,
    last_heartbeat_at    INTEGER,
    -- Pointer into task_runs for the currently-active run (NULL if no
    -- run is in-flight). Denormalised for cheap reads.
    current_run_id       INTEGER,
    -- Forward-compat for v2 workflow routing. In v1 the kernel writes
    -- these when the task is opted into a template but otherwise ignores
    -- them; the dispatcher doesn't consult them for routing yet.
    workflow_template_id TEXT,
    current_step_key     TEXT,
    -- Force-loaded skills for the worker on this task, stored as JSON.
    -- Appended to the dispatcher's built-in `--skills kanban-worker`.
    -- NULL or empty array = no extras.
    skills               TEXT,
    -- Per-task model override. When set, the dispatcher passes -m <model>
    -- to the worker, overriding the profile's default model. NULL = use
    -- the profile default.
    model_override       TEXT,
    -- Per-task override for the consecutive-failure circuit breaker.
    -- The value is the failure count at which the breaker trips — e.g.
    -- ``max_retries=1`` blocks on the first failure. NULL (the common
    -- case) falls through to the dispatcher-level ``kanban.failure_limit``
    -- config and then ``DEFAULT_FAILURE_LIMIT``.
    max_retries          INTEGER,
    -- Originating chat/agent session id when the task was created from
    -- inside an agent loop that propagated ``HERMES_SESSION_ID``. NULL
    -- for tasks created from the CLI, dashboard, or any path that doesn't
    -- set the env var. Indexed so per-session list queries stay cheap on
    -- larger boards.
    session_id           TEXT
);
CREATE TABLE task_links (
    parent_id  TEXT NOT NULL,
    child_id   TEXT NOT NULL,
    PRIMARY KEY (parent_id, child_id)
);
CREATE TABLE task_comments (
    id         INTEGER PRIMARY KEY AUTOINCREMENT,
    task_id    TEXT NOT NULL,
    author     TEXT NOT NULL,
    body       TEXT NOT NULL,
    created_at INTEGER NOT NULL
);
CREATE TABLE task_events (
    id         INTEGER PRIMARY KEY AUTOINCREMENT,
    task_id    TEXT NOT NULL,
    run_id     INTEGER,
    kind       TEXT NOT NULL,
    payload    TEXT,
    created_at INTEGER NOT NULL
);
CREATE TABLE task_runs (
    id                  INTEGER PRIMARY KEY AUTOINCREMENT,
    task_id             TEXT NOT NULL,
    profile             TEXT,
    step_key            TEXT,
    status              TEXT NOT NULL,
    -- status: running | done | blocked | crashed | timed_out | failed | released
    claim_lock          TEXT,
    claim_expires       INTEGER,
    worker_pid          INTEGER,
    max_runtime_seconds INTEGER,
    last_heartbeat_at   INTEGER,
    started_at          INTEGER NOT NULL,
    ended_at            INTEGER,
    outcome             TEXT,
    -- outcome: completed | blocked | crashed | timed_out | spawn_failed |
    --          gave_up | reclaimed | (null while still running)
    summary             TEXT,
    metadata            TEXT,
    error               TEXT
);
CREATE TABLE kanban_notify_subs (
    task_id       TEXT NOT NULL,
    platform      TEXT NOT NULL,
    chat_id       TEXT NOT NULL,
    thread_id     TEXT NOT NULL DEFAULT '',
    user_id       TEXT,
    notifier_profile TEXT,
    created_at    INTEGER NOT NULL,
    last_event_id INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (task_id, platform, chat_id, thread_id)
);
INSERT OR IGNORE INTO 'tasks'(_rowid_, 'id', 'title', 'body', 'assignee', 'status', 'priority', 'created_by', 'created_at', 'started_at', 'completed_at', 'workspace_kind', 'workspace_path', 'branch_name', 'claim_lock', 'claim_expires', 'tenant', 'result', 'idempotency_key', 'consecutive_failures', 'worker_pid', 'last_failure_error', 'max_runtime_seconds', 'last_heartbeat_at', 'current_run_id', 'workflow_template_id', 'current_step_key', 'skills', 'model_override', 'max_retries', 'session_id') VALUES (32, 't_4e962fef', 'ssh-mcp: HTTP MCP transport + Windows Kerberos compatibility (rev 2)', replace('Implement Streamable HTTP MCP transport for ssh-mcp-kerberos (Option B per P2 design).\n\nWORKSPACE (ground truth — already set up by orchestrator):\n- Worktree path: /home/islaliu/Repositories/ssh-mcp-kerberos.wt/http-transport\n- Branch: feat/openssh-transport-kerberos-integration\n- This branch already has feat/toml-config + feat/approval-engine merged (commit b776e7a). You work HERE; do NOT touch other worktrees.\n- audit-log work is NOT yet merged (its source worktree wt/audit-log has uncommitted state — separate sibling review will resolve). Treat audit-log as an interface stub for now: define expected fields (transport, remote_addr, bearer_present) and call out a TODO comment in audit hook points; the audit-log integration card will land separately.\n\nPORT POLICY (user authoritative, 2026-05-26):\n- Production / default: 8934 — sane reuse of the current mcp-proxy port so migration just stops the bridge and starts ssh-mcp directly. NO firewall change needed (Hyper-V ''_Mcp Servers Allow Wsl only'' already opens 8931-8939 for MCPs; 8934 in that range).\n- Tests: ANY free port is acceptable; use ephemeral ports or env override (SSH_MCP_HTTP_PORT) to avoid clashing with a running production instance.\n- Do NOT use 7022 from the P2 plan; user reserved 8931-8939 for MCPs.\n- TOML [server.http].port default value in code: 8934.\n\nINPUTS:\n- P2 pla������u"���������i]QH<���0','\n', char(10)), 'blockeddo', 'ne', 98, 'lock', 1701054733, 52363634, NULL, 'ecl', replace(replace('aimeddone\nn\rreclaimedblockedblockedblo','\n', char(10)),'\r', char(13)), NULL, NULL, NULL, NULL, NULL, 'ckedblockeddoneng', 0, NULL, NULL, 5385, 1685024357, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO 'tasks'(_rowid_, 'id', 'title', 'body', 'assignee', 'status', 'priority', 'created_by', 'created_at', 'started_at', 'completed_at', 'workspace_kind', 'workspace_path', 'branch_name', 'claim_lock', 'claim_expires', 'tenant', 'result', 'idempotency_key', 'consecutive_failures', 'worker_pid', 'last_failure_error', 'max_runtime_seconds', 'last_heartbeat_at', 'current_run_id', 'workflow_template_id', 'current_step_key', 'skills', 'model_override', 'max_retries', 'session_id') VALUES (33, 't_0c08267c', 'REVIEW: http-transport + windows kerberos (rev 2)', replace('Acceptance review for HTTP MCP transport + Windows Kerberos card.\n\nTriggered when the developer card calls kanban_block with ''review-required:'' as prefix. Use sibling-pattern if dependency semantics keep this card todo: orchestrator will spawn a no-parent sibling reviewer when the producer is still blocked at review time.\n\nPass criteria:\n- stdio transport behaviour preserved with no regressions in existing test/openssh.unit.test.ts.\n- HTTP transport boots only when [server.http].enabled=true OR --transport-mcp=http.\n- Bearer token enforced; 401 without it.\n- enableDnsRebindingProtection=true verified; allowedHosts/allowedOrigins actually rejects spoofed requests.\n- Non-loopback bind without auth_token = fatal at boot (test demonstrates).\n- Audit hook receives transport / remote_addr / bearer_present; bearer NEVER appears in any log, status, or stderr (grep the test artifacts).\n- Multi-instance race: runtime.json + pid liveness check prevents stale dual-boot within 2-min freshness window.\n- Approval engine still wired BEFORE transport.exec for both transports.\n- Port default in code = 8934; tests may use any free port; no 7022 leftover from P2.\n- README/comments mention that production uses 8934 (mcp-proxy migration target).\n\nOn PASS: unblock parent (kanban_unblock) and drop verification evidence comment.\nOn FAIL/YELLOW/RED: keep blocked; comment with exact file:line defects and required fixes.\n','\n', char(10)), 'reviewer', 'todo', 84, 'user', 1779762943, NULL, NULL, 'dir', '/home/islaliu/Repositories/ssh-mcp-kerberos', NULL, NULL, NULL, NULL, NULL, 'ssh-mcp-review-http-transport-rev2', 0, NULL, NULL, 2700, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO 'tasks'(_rowid_, 'id', 'title', 'body', 'assignee', 'status', 'priority', 'created_by', 'created_at', 'started_at', 'completed_at', 'workspace_kind', 'workspace_path', 'branch_name', 'claim_lock', 'claim_expires', 'tenant', 'result', 'idempotency_key', 'consecutive_failures', 'worker_pid', 'last_failure_error', 'max_runtime_seconds', 'last_heartbeat_at', 'current_run_id', 'workflow_template_id', 'current_step_key', 'skills', 'model_override', 'max_retries', 'session_id') VALUES (1, 't_b94988d2', 'EPIC: ssh-mcp-kerberos TOML config, audit logging, approvals, WebUI status', 'Goal: analyze /home/islaliu/Repositories/ssh-mcp-kerberos and implement first-class TOML configuration, command audit logging, smart/manual/yolo approval modes, and dbhub-style WebUI-visible status. Preserve existing --ssh behavior and MCP compatibility.\n\nUser request:\n1. Besides existing --ssh config, mimic /home/islaliu/Repositories/dbhub .toml configuration so multiple profiles can be adjusted in TOML and status can be presented in WebUI like dbhub.\n2. Log every executed command; suggested storage like %USERPROFILE%\.ssh-mcp (WSL/Linux equivalent ~/.ssh-mcp).\n3. Reference Hermes Agent smart approvals: ssh-mcp should support LLM auth endpoint, API key, model name settings; provide yolo, smart, manual modes. In smart mode, LLM decides whether to allow/deny based on TOML description, requested command, and command description match. Decision and records should be visible in WebUI. In manual mode, WebUI should show pending approval in real time and allow approval/denial.\n\nCoordinator constraints:\n- Do not ask user unless a security decision or implementation ambiguity cannot be resolved safely.\n- Production/security posture: fail closed for smart approval errors unless explicitly configured otherwise.\n- Keep external-facing docs and names self-explanatory; avoid internal card/session jargon in user-facing artifacts.\n- Prefer structural enforcement and tests over prose-only safeguards.\n- If a task edits git, use isolated worktree/branch; do not touch unrelated worktrees.\n\nDefinition of done:\n- Existing --ssh path still works without TOML.\n- TOML multi-profile config works with documented precedence.\n- Command audit logs are written with secret redaction and bounded output.\n- Approval engine supports yolo/smart/manual with tests.\n- WebUI/status surface exposes profiles, connection status, recent executions, approval mode, smart decisions, pending manual approvals.\n- Reviewer PASS.\n- Documentation/examples added after reviewer PASS.', 'planner', 'done', 100, 'user', 1779696964, 1779697014, 1779697273, 'dir', '/home/islaliu/Repositories/ssh-mcp-kerberos', NULL, NULL, NULL, NULL, NULL, 'epic-ssh-mcp-kerberos-config-logging-approvals-webui', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO 'tasks'(_rowid_, 'id', 'title', 'body', 'assignee', 'status', 'priority', 'created_by', 'created_at', 'started_at', 'completed_at', 'workspace_kind', 'workspace_path', 'branch_name', 'claim_lock', 'claim_expires', 'tenant', 'result', 'idempotency_key', 'consecutive_failures', 'worker_pid', 'last_failure_error', 'max_runtime_seconds', 'last_heartbeat_at', 'current_run_id', 'workflow_template_id', 'current_step_key', 'skills', 'model_override', 'max_retries', 'session_id') VALUES (2, 't_2b983502', 'R0: research ssh-mcp-kerberos and dbhub TOML/status patterns', replace('Purpose: research the current ssh-mcp-kerberos implementation and the dbhub repository''s TOML/status patterns before any implementation.\n\nScope:\n- Inspect /home/islaliu/Repositories/ssh-mcp-kerberos.\n- Inspect /home/islaliu/Repositories/dbhub if present; if not present, block with exact missing path and what evidence is needed.\n- Do not modify files.\n\nRequired findings:\n1. Current ssh-mcp-kerberos CLI/config/auth/command execution flow.\n2. Current MCP tools exposed by ssh-mcp-kerberos and how status/metadata are surfaced.\n3. dbhub TOML config schema, config search paths, profile/multiple connection model, and how dbhub exposes WebUI-visible status.\n4. Which dbhub patterns can be reused and which are inappropriate for ssh remote execution.\n5. Any existing test layout and commands for ssh-mcp-kerberos.\n6. Security-sensitive ambiguities that require planner/reviewer attention.\n\nDeliverable in task result:\n- Short architecture map with file paths.\n- Proposed ssh-mcp TOML schema sketch.\n- Recommended WebUI/status contract.\n- Risks and unknowns.\n','\n', char(10)), 'researcher', 'done', 95, 'user', 1779697104, 1779697314, 1779697577, 'dir', '/home/islaliu/Repositories/ssh-mcp-kerberos', NULL, NULL, NULL, NULL, NULL, 'ssh-mcp-r0-research-dbhub-patterns', 0, NULL, NULL, 2700, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO 'tasks'(_rowid_, 'id', 'title', 'body', 'assignee', 'status', 'priority', 'created_by', 'created_at', 'started_at', 'completed_at', 'workspace_kind', 'workspace_path', 'branch_name', 'claim_lock', 'claim_expires', 'tenant', 'result', 'idempotency_key', 'consecutive_failures', 'worker_pid', 'last_failure_error', 'max_runtime_seconds', 'last_heartbeat_at', 'current_run_id', 'workflow_template_id', 'current_step_key', 'skills', 'model_override', 'max_retries', 'session_id') VALUES (3, 't_08647b01', 'P1: design TOML config, audit log, approval engine, WebUI status contract', replace('Purpose: convert R0 findings into a concrete implementation specification for ssh-mcp-kerberos.\n\nUse parent result from R0. Do not implement code.\n\nDesign requirements:\n- Preserve existing --ssh configuration behavior and MCP compatibility.\n- Add TOML multi-profile config similar in spirit to dbhub, but adapted for SSH security.\n- Define config search paths and precedence:\n  1. explicit CLI args / legacy --ssh\n  2. explicit --config / --profile\n  3. default TOML profile\n  4. built-in defaults\n- Define secret handling: API keys should prefer environment variable references over plaintext TOML.\n- Define audit log schema and storage path. Recommended default:\n  - Windows: %USERPROFILE%\.ssh-mcp\logs\n  - Linux/WSL: ~/.ssh-mcp/logs\n- Define approval modes:\n  - manual: pending approval visible via status/WebUI and requires approve/deny\n  - smart: LLM decides using TOML descriptions, requested command, command description, risk signals; fail closed by default\n  - yolo: allow without prompt but still audit log\n- Define WebUI/status contract and MCP tool/API names needed for WebUI integration.\n- Define tests and acceptance criteria.\n\nSecurity decisions default policy unless reviewer/user overrides:\n- smart approval errors deny by default.\n- command/log/status output redacts credential-like strings.\n- logs cap stdout/stderr or store bounded summaries.\n- manual approval uses stable request id and timeout.\n- no real destructive remote commands in tests.\n\nDeliverable:\n- Implementation plan with concrete files/modules to change.\n- Data schemas for TOML, logs, approval records, status response.\n- Test matrix.\n- Explicit open questions, if any, labeled GREEN/YELLOW/RED.\n','\n', char(10)), 'planner', 'archived', 90, 'user', 1779697104, 1779697615, NULL, 'dir', '/home/islaliu/Repositories/ssh-mcp-kerberos', NULL, NULL, NULL, NULL, NULL, 'ssh-mcp-p1-design-config-logging-approvals-webui', 0, NULL, NULL, 3600, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO 'tasks'(_rowid_, 'id', 'title', 'body', 'assignee', 'status', 'priority', 'created_by', 'created_at', 'started_at', 'completed_at', 'workspace_kind', 'workspace_path', 'branch_name', 'claim_lock', 'claim_expires', 'tenant', 'result', 'idempotency_key', 'consecutive_failures', 'worker_pid', 'last_failure_error', 'max_runtime_seconds', 'last_heartbeat_at', 'current_run_id', 'workflow_template_id', 'current_step_key', 'skills', 'model_override', 'max_retries', 'session_id') VALUES (4, 't_278be576', 'V1: security review implementation design before coding', replace('Purpose: security and feasibility review of P1 design before implementation.\n\nDo not edit code. Review the plan for remote-command safety and implementation ambiguity.\n\nPASS only if:\n- Existing --ssh behavior remains backward compatible.\n- TOML schema avoids plaintext secret requirements and supports env references for LLM API key.\n- Approval modes are unambiguous: yolo, smart, manual.\n- smart mode fails closed on provider errors unless explicitly configured otherwise.\n- smart prompt/input uses connection/profile descriptions and requested command description, but cannot be trivially bypassed by description mismatch.\n- manual mode has a stable pending request id, timeout policy, and approve/deny transition.\n- audit log schema redacts secrets and bounds stdout/stderr.\n- WebUI/status contract exposes pending approvals and decisions without leaking secrets.\n- Test plan covers allow/deny/error/manual/status/logging/backward compatibility.\n\nIf PASS: summarize the approved constraints developer must obey.\nIf FAIL/YELLOW: block with exact questions for user or planner; do not allow implementation to proceed.\n','\n', char(10)), 'reviewer', 'archived', 88, 'user', 1779697105, NULL, NULL, 'dir', '/home/islaliu/Repositories/ssh-mcp-kerberos', NULL, NULL, NULL, NULL, NULL, 'ssh-mcp-v1-security-design-review', 0, NULL, NULL, 2700, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO 'tasks'(_rowid_, 'id', 'title', 'body', 'assignee', 'status', 'priority', 'created_by', 'created_at', 'started_at', 'completed_at', 'workspace_kind', 'workspace_path', 'branch_name', 'claim_lock', 'claim_expires', 'tenant', 'result', 'idempotency_key', 'consecutive_failures', 'worker_pid', 'last_failure_error', 'max_runtime_seconds', 'last_heartbeat_at', 'current_run_id', 'workflow_template_id', 'current_step_key', 'skills', 'model_override', 'max_retries', 'session_id') VALUES (5, 't_144d7c10', 'D0: draft README/examples for TOML logging and approval modes', replace('Purpose: draft user-facing documentation/examples for the new ssh-mcp TOML/logging/approval features so implementation can include clear docs in one branch.\n\nUse parent design/review results. Prefer producing text in the task result; do not edit repo unless the implementation card explicitly hands you a branch later.\n\nDraft sections:\n1. Minimal TOML config.\n2. Multiple SSH profiles.\n3. Legacy --ssh compatibility and precedence.\n4. Audit log location and JSONL example.\n5. smart approval config with endpoint/api_key_env/model.\n6. manual approval flow and WebUI-visible pending requests.\n7. yolo warning and audit behavior.\n8. Security guidance: do not store API keys directly in TOML; use env references.\n9. Windows/WSL/Linux path notes for ~/.ssh-mcp vs %USERPROFILE%\.ssh-mcp.\n\nDeliverable:\n- Markdown-ready draft sections and example TOML blocks.\n- Any wording cautions developer should preserve in README/docs.\n','\n', char(10)), 'documenter', 'archived', 84, 'user', 1779697105, NULL, NULL, 'dir', '/home/islaliu/Repositories/ssh-mcp-kerberos', NULL, NULL, NULL, NULL, NULL, 'ssh-mcp-d0-doc-draft-toml-logging-approvals', 0, NULL, NULL, 2700, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO 'tasks'(_rowid_, 'id', 'title', 'body', 'assignee', 'status', 'priority', 'created_by', 'created_at', 'started_at', 'completed_at', 'workspace_kind', 'workspace_path', 'branch_name', 'claim_lock', 'claim_expires', 'tenant', 'result', 'idempotency_key', 'consecutive_failures', 'worker_pid', 'last_failure_error', 'max_runtime_seconds', 'last_heartbeat_at', 'current_run_id', 'workflow_template_id', 'current_step_key', 'skills', 'model_override', 'max_retries', 'session_id') VALUES (6, 't_9cbacb2a', 'DEV: implement TOML config, audit logs, approvals, and WebUI status', replace('Purpose: implement the approved ssh-mcp-kerberos feature set in one isolated git worktree/branch.\n\nParents provide: research, final design, security review constraints, and doc draft. If V1 is not PASS or contains unresolved YELLOW/RED decisions, block and report exact questions instead of coding.\n\nWorkspace/branch constraints:\n- Work only in this task''s isolated worktree/branch.\n- Do not touch the main checkout or other worktrees.\n- Do not run destructive remote commands. Tests must use mocks/fakes/local fixtures.\n- Preserve existing --ssh behavior when no TOML is present.\n\nImplement:\n1. TOML config loader and multi-profile support.\n   - Default paths: Windows %USERPROFILE%\.ssh-mcp\config.toml; Linux/WSL ~/.ssh-mcp/config.toml.\n   - Env override if appropriate, e.g. SSH_MCP_CONFIG.\n   - CLI support for explicit config/profile/listing as designed.\n   - TOML descriptions available to approval engine and status.\n2. Command audit logging.\n   - JSONL or approved store under ~/.ssh-mcp/logs by default.\n   - Log allow/deny/error/execution result for every command request.\n   - Redact credential-like data and bound stdout/stderr.\n   - Logging failure should not crash command execution unless strict mode is configured.\n3. Approval engine.\n   - yolo/manual/smart modes.\n   - smart calls configured endpoint/model/api key env reference and parses structured decision.\n   - Fail closed on smart errors by default.\n   - manual creates stable pending approval records and supports approve/deny lifecycle.\n4. WebUI/status integration.\n   - Expose dbhub-style status for profiles, active/default profile, connection status, recent commands, approval mode, smart decisions, pending manual approvals.\n   - Add MCP tools or status endpoints per design, e.g. get status/list logs/list pending/approve/deny.\n5. Documentation integration.\n   - Incorporate D0 draft into README/docs/examples as appropriate.\n\nTesting:\n- Add/update automated tests for no-config fallback, legacy --ssh, TOML parsing, profile selection, invalid config errors, audit logs, secret redaction, smart allow/deny/error fallback, manual pending/approve/deny, and status output.\n- Run the repo''s relevant tests and report exact command/output summary.\n\nCompletion result must include:\n- Branch/worktree path.\n- Files changed summary.\n- Test commands run and results.\n- Any intentionally deferred items or risks.\n','\n', char(10)), 'developer-general', 'archived', 80, 'user', 1779697105, NULL, NULL, 'worktree', NULL, 'feat/ssh-mcp-toml-approvals-webui', NULL, NULL, NULL, NULL, 'ssh-mcp-dev-implement-toml-logging-approvals-webui', 0, NULL, NULL, 10800, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO 'tasks'(_rowid_, 'id', 'title', 'body', 'assignee', 'status', 'priority', 'created_by', 'created_at', 'started_at', 'completed_at', 'workspace_kind', 'workspace_path', 'branch_name', 'claim_lock', 'claim_expires', 'tenant', 'result', 'idempotency_key', 'consecutive_failures', 'worker_pid', 'last_failure_error', 'max_runtime_seconds', 'last_heartbeat_at', 'current_run_id', 'workflow_template_id', 'current_step_key', 'skills', 'model_override', 'max_retries', 'session_id') VALUES (7, 't_e5df6872', 'V2: final acceptance review for ssh-mcp TOML/logging/approval/WebUI feature', replace('Purpose: final acceptance review of the implementation. Do not modify code except, if policy allows, tiny review notes/comments; prefer PASS/FAIL with evidence.\n\nReview inputs: all parent task results, implementation branch/worktree, and tests.\n\nAcceptance criteria:\n- Legacy --ssh behavior still works with no TOML.\n- TOML multi-profile config works and precedence is documented/tested.\n- API keys/secrets are not required in plaintext TOML; env reference path works.\n- Every command request gets an audit record for allow/deny/error/executed cases.\n- Logs/status redact credential-like data and bound stdout/stderr.\n- yolo mode permits execution and logs decision.\n- smart mode allow/deny works with structured LLM response; endpoint failure/schema failure defaults to deny unless config says otherwise.\n- manual mode creates stable pending id; status/WebUI surface shows pending; approve/deny changes execution behavior.\n- WebUI/status surface exposes configured profiles, active/default profile, connection/health, recent commands, approval mode, smart decisions, pending manual approvals.\n- Tests cover core behavior; no real destructive remote commands used.\n- Docs/examples are clear and self-contained.\n\nIf PASS:\n- Summarize verification evidence and whether branch is ready for user review/push.\nIf FAIL:\n- Block or report exact defects with file/path/test evidence and recommended next card.\n','\n', char(10)), 'reviewer', 'blocked', 70, 'user', 1779697106, 1779697735, NULL, 'dir', '/home/islaliu/Repositories/ssh-mcp-kerberos', NULL, NULL, NULL, NULL, NULL, 'ssh-mcp-v2-final-acceptance-review', 0, NULL, NULL, 5400, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO 'tasks'(_rowid_, 'id', 'title', 'body', 'assignee', 'status', 'priority', 'created_by', 'created_at', 'started_at', 'completed_at', 'workspace_kind', 'workspace_path', 'branch_name', 'claim_lock', 'claim_expires', 'tenant', 'result', 'idempotency_key', 'consecutive_failures', 'worker_pid', 'last_failure_error', 'max_runtime_seconds', 'last_heartbeat_at', 'current_run_id', 'workflow_template_id', 'current_step_key', 'skills', 'model_override', 'max_retries', 'session_id') VALUES (8, 't_211f6446', 'CLOSE: ssh-mcp-kerberos', replace('Close this board after V2 final PASS.\n\nFollow: ~/.hermes/skills/devops/kanban-orchestrator/references/closing-board-with-archiver.md\n\nRules:\n- Green facts auto-ingest into durable memory/skills only if stable and useful beyond this board.\n- Yellow blocks/questions must be reported to the user.\n- Red/transient implementation chatter is discarded.\n- Do not archive if V2 failed or is blocked; instead report the blocker.\n','\n', char(10)), 'fleet-archiver', 'todo', 10, 'user', 1779697106, NULL, NULL, 'dir', '/home/islaliu/Repositories/ssh-mcp-kerberos', NULL, NULL, NULL, NULL, NULL, 'ssh-mcp-close-board-archiver', 0, NULL, NULL, 1800, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO 'tasks'(_rowid_, 'id', 'title', 'body', 'assignee', 'status', 'priority', 'created_by', 'created_at', 'started_at', 'completed_at', 'workspace_kind', 'workspace_path', 'branch_name', 'claim_lock', 'claim_expires', 'tenant', 'result', 'idempotency_key', 'consecutive_failures', 'worker_pid', 'last_failure_error', 'max_runtime_seconds', 'last_heartbeat_at', 'current_run_id', 'workflow_template_id', 'current_step_key', 'skills', 'model_override', 'max_retries', 'session_id') VALUES (9, 't_2d87e8fa', 'ssh-mcp: TOML multi-profile config loader + precedence', replace('Implement first-class TOML config for ssh-mcp-kerberos, mirroring dbhub''s shape.\n\nPlan reference: /home/islaliu/Repositories/ssh-mcp-kerberos/.hermes/plans/2026-05-25_ssh-mcp-toml-audit-approvals-webui.md (sections "TOML schema", "Tasks > 1. toml-config").\n\nScope:\n- New files: src/config/types.ts, src/config/toml-loader.ts, src/config/resolver.ts, src/config/__tests__/{toml-loader,resolver}.test.ts.\n- Add @iarna/toml (or similar zero-native-dep TOML parser) to dependencies.\n- Wire into src/index.ts so --config=path works alongside existing --ssh=<JSON> and legacy single-host flags.\n- Precedence (high->low): CLI flags > --config TOML > SSH_MCP_CONFIG env > $XDG_CONFIG_HOME/ssh-mcp/config.toml > ~/.ssh-mcp/config.toml.\n- env:NAME resolution at load time; missing env -> validation error.\n- Passwords never logged.\n\nAcceptance (DoD):\n- `npm test` green.\n- Sample ssh-mcp.toml.example with two [[sources]] registers identically to equivalent --ssh=<JSON> calls.\n- Legacy CLI path unchanged when no TOML present (existing tests pass untouched).\n- Add a unit test that asserts CLI > TOML precedence.\n\nDo NOT implement audit logging, approvals, or WebUI in this task. Those are separate cards. Stop at config loading and registry wiring.\n\nBranch/worktree: use the worktree workspace; do not touch other worktrees. Open PR against feat/openssh-transport-kerberos.\n\nEnd with kanban_block(reason="review-required: TOML config + precedence") after dropping a kanban_comment with {changed_files, tests_run, diff_path}.','\n', char(10)), 'developer-general', 'done', 90, 'planner', 1779697214, 1779697315, 1779763029, 'worktree', '/home/islaliu/Repositories/ssh-mcp-kerberos.wt/toml-config', NULL, NULL, NULL, NULL, 'PASS-with-caveats per sibling review t_f8036377. 38/38 TOML tests + 31/31 pre-existing unit tests pass. YELLOW: docs/examples deferred to docs cards. Commit 6e0df80 on feat/toml-config branch; merged into integration branch as b776e7a.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '20260525_161656_f2d68f');
INSERT OR IGNORE INTO 'tasks'(_rowid_, 'id', 'title', 'body', 'assignee', 'status', 'priority', 'created_by', 'created_at', 'started_at', 'completed_at', 'workspace_kind', 'workspace_path', 'branch_name', 'claim_lock', 'claim_expires', 'tenant', 'result', 'idempotency_key', 'consecutive_failures', 'worker_pid', 'last_failure_error', 'max_runtime_seconds', 'last_heartbeat_at', 'current_run_id', 'workflow_template_id', 'current_step_key', 'skills', 'model_override', 'max_retries', 'session_id') VALUES (10, 't_67320e65', 'ssh-mcp: command audit log (~/.ssh-mcp, JSONL, redaction, rotation)', replace('Implement persistent command audit log for ssh-mcp-kerberos.\n\nPlan reference: /home/islaliu/Repositories/ssh-mcp-kerberos/.hermes/plans/2026-05-25_ssh-mcp-toml-audit-approvals-webui.md (section "Audit log", "Tasks > 2. audit-log").\n\nScope:\n- New files: src/audit/{types,redactor,store,rotator}.ts plus tests under src/audit/__tests__/.\n- Default audit dir: ~/.ssh-mcp (Windows: %USERPROFILE%/.ssh-mcp). Overridable via TOML [server].audit_dir (from the toml-config card).\n- JSONL append, one record per execution; rotate at 10MB, keep 10 files; also roll on day boundary.\n- Redactor scrubs passwords/keys/tokens from command, description, stdout, stderr (rules in plan).\n- Bounded output: per-record stdout/stderr capped at [server].audit_max_bytes (default 10000); set truncated flag.\n- Wire into exec + sudo-exec MCP tool handlers in src/index.ts: append AFTER execution (denied or allowed); for denied executions (from approval engine - landing in a later card), still append a record. For now, append on success/failure; placeholders for approval fields are fine.\n\nAcceptance (DoD):\n- `npm test` green.\n- Unit tests: redactor (password regex, PEM, AWS/JWT shapes); store (append, day-roll, size-roll); rotator (size cap, retention).\n- Integration check: after an exec succeeds against a stub transport, a JSONL line exists at expected path with redacted command and capped stdout.\n- No regression in test/openssh.unit.test.ts.\n\nDepends on parent task only for the audit_dir TOML key; if toml-config card has not landed yet, hard-code default and add a TODO referencing TOML wiring.\n\nEnd with kanban_block(reason="review-required: audit log") after dropping {changed_files, tests_run, diff_path} as a comment.','\n', char(10)), 'developer-general', 'done', 85, 'planner', 1779697215, 1779697315, 1779763030, 'worktree', '/home/islaliu/Repositories/ssh-mcp-kerberos.wt/audit-log', NULL, NULL, NULL, NULL, 'PASS per sibling review t_66e61c98. 28/28 audit + openssh.unit tests pass. Commit 352287e on wt/audit-log branch (committed by AM during integration because dev left it dirty). YELLOW: no strict-mode toggle; TOML wiring deferred to integration card. To be merged into integration by DEV_HTTP rev2 (t_4e962fef).', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '20260525_161656_f2d68f');
INSERT OR IGNORE INTO 'tasks'(_rowid_, 'id', 'title', 'body', 'assignee', 'status', 'priority', 'created_by', 'created_at', 'started_at', 'completed_at', 'workspace_kind', 'workspace_path', 'branch_name', 'claim_lock', 'claim_expires', 'tenant', 'result', 'idempotency_key', 'consecutive_failures', 'worker_pid', 'last_failure_error', 'max_runtime_seconds', 'last_heartbeat_at', 'current_run_id', 'workflow_template_id', 'current_step_key', 'skills', 'model_override', 'max_retries', 'session_id') VALUES (11, 't_c857745f', 'ssh-mcp: approval engine (yolo/smart/manual) with fail-closed smart mode', replace('Implement approval engine for ssh-mcp-kerberos: yolo, smart (LLM), manual.\n\nPlan reference: /home/islaliu/Repositories/ssh-mcp-kerberos/.hermes/plans/2026-05-25_ssh-mcp-toml-audit-approvals-webui.md (section "Approval engine", "Tasks > 3. approval-engine").\n\nScope:\n- New files: src/approval/{types,engine,yolo,smart,manual}.ts plus tests under src/approval/__tests__/.\n- Engine dispatches by mode; per-source override via TOML [sources.approval].\n- yolo: always allow.\n- smart: POST to configured LLM endpoint (OpenAI chat-completions schema as default; provider field allows future Anthropic/Azure). Structured JSON response {allow, reason}. Timeout, non-200, malformed JSON -> fail_closed (default true) deny; otherwise allow with warning. Use a fetch wrapper that is easily stubbed in tests.\n- manual: enqueue PendingApproval keyed by ULID; resolver awaits external signal (WebUI - landing in next card). 5-min default timeout -> deny with "approval timed out".\n- Manual mode fatally errors at startup if WebUI is disabled.\n- Wire engine into exec + sudo-exec handlers BEFORE transport.exec; on deny, throw McpError with the reason; on allow, proceed and pass approval block into audit record.\n\nAcceptance (DoD):\n- `npm test` green.\n- Unit tests cover: yolo allow; smart allow, deny, timeout, malformed JSON, non-200 (all under fail-closed and fail-open settings); manual queue + external resolve + timeout.\n- Integration: with mode=yolo, exec runs unchanged; with mode=smart + stubbed allow, exec runs; with mode=smart + stubbed deny, exec is blocked with a clear McpError.\n- Manual mode without WebUI throws at boot.\n\nDepends conceptually on toml-config + audit-log, but should not block on them — define ResolvedSource/ApprovalContext types locally if needed; reviewer will tie them together.\n\nEnd with kanban_block(reason="review-required: approval engine") after dropping {changed_files, tests_run, diff_path} as a comment.','\n', char(10)), 'developer-general', 'done', 80, 'planner', 1779697217, 1779697315, 1779763030, 'worktree', '/home/islaliu/Repositories/ssh-mcp-kerberos.wt/approval-engine', NULL, NULL, NULL, NULL, 'PASS per sibling review t_a2698fcc. 35/35 approval tests pass; no secret leakage; legacy behavior preserved. Commit eb7bd7d on feat/approval-engine; merged into integration branch as b776e7a.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '20260525_161656_f2d68f');
INSERT OR IGNORE INTO 'tasks'(_rowid_, 'id', 'title', 'body', 'assignee', 'status', 'priority', 'created_by', 'created_at', 'started_at', 'completed_at', 'workspace_kind', 'workspace_path', 'branch_name', 'claim_lock', 'claim_expires', 'tenant', 'result', 'idempotency_key', 'consecutive_failures', 'worker_pid', 'last_failure_error', 'max_runtime_seconds', 'last_heartbeat_at', 'current_run_id', 'workflow_template_id', 'current_step_key', 'skills', 'model_override', 'max_retries', 'session_id') VALUES (12, 't_4e2a635b', 'ssh-mcp: WebUI status surface (profiles, executions, approvals, SSE)', replace('Implement dbhub-style WebUI status surface for ssh-mcp-kerberos.\n\nPlan reference: /home/islaliu/Repositories/ssh-mcp-kerberos/.hermes/plans/2026-05-25_ssh-mcp-toml-audit-approvals-webui.md (section "WebUI", "Tasks > 4. webui-status").\n\nScope:\n- New files: src/webui/server.ts, src/webui/routes/{profiles,executions,approvals,sse}.ts, src/webui/static/* (single-page vanilla JS, no build step), src/webui/__tests__/routes.test.ts.\n- Express + SSE. Off by default; opt-in via TOML [webui].enabled = true or --webui CLI flag.\n- Defaults to 127.0.0.1; non-loopback bind REQUIRES auth_token at boot (fatal error otherwise).\n- Bearer token check on /api/* and ?token= for SSE.\n- Routes:\n  - GET /api/profiles -> registry snapshot + effective approval mode per profile\n  - GET /api/executions?profile=&limit= (default 100, max 1000) -> tail of audit JSONL\n  - GET /api/approvals -> pending manual approvals (from approval/manual queue)\n  - POST /api/approvals/:id/{allow,deny} body {note?: string}\n  - GET /events (SSE) push pending-approval and execution events\n- Static UI: three panels (Profiles / Recent Executions / Pending Approvals), polling profiles + subscribing to /events.\n\nAcceptance (DoD):\n- `npm test` green.\n- Integration test boots server on ephemeral port, asserts each route shape, asserts manual approval round-trip (enqueue -> GET shows it -> POST allow -> engine.decide promise resolves with allow).\n- Static page loads via curl with token; without token returns 401 on non-loopback. Loopback requires token only if [webui].auth_token set.\n- No regressions in existing tests.\n\nDepends on approval-engine card for the manual queue interface; if not landed yet, define the interface stub and let reviewer reconcile.\n\nEnd with kanban_block(reason="review-required: webui status surface") after dropping {changed_files, tests_run, diff_path} as a comment.','\n', char(10)), 'developer-general', 'done', 75, 'planner', 1779697243, 1779697315, 1779763030, 'worktree', '/home/islaliu/Repositories/ssh-mcp-kerberos.wt/webui', NULL, NULL, NULL, NULL, 'PASS-with-caveats per sibling review t_b6b0762e. 13/13 webui tests pass; all 8 acceptance criteria met. YELLOW: node:http accepted (user OK with this); src/index.ts boot wiring deferred to integration card. Commit e76f776 on wt/webui — NOT yet merged into integration branch (DEV_HTTP rev2 owns that merge after audit-log merge clears).', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '20260525_161656_f2d68f');
