r', 1779697245, NULL, NULL, 'worktree', '/home/islaliu/Repositories/ssh-mcp-kerberos.wt/e2e-smoke', NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '20260525_161656_f2d68f');
