INSERT OR IGNORE INTO 'task_comments'('id', 'task_id', 'author', 'body', 'created_at') VALUES (1, 't_b94988d2', 'orchestrator', 'Planner (t_b94988d2 run #1) bypassed the design-time V1 security gate by fanning out four implementation cards directly (TOML/audit/approval/webui) without waiting for reviewer sign-off. Workers were already running in isolated worktrees, so the orchestrator did not interrupt them. Compensating controls applied: per-impl reviewer cards now gate each block(review-required), a consolidated security audit (S1) gates e2e, docs gates V2, V2 gates CLOSE. Old V1/DEV/D0 cards archived as superseded.', 1779697701);
INSERT OR IGNORE INTO 'task_comments'('id', 'task_id', 'author', 'body', 'created_at') VALUES (2, 't_2d87e8fa', 'orchestrator', 'When you finish, call kanban_block with reason starting with ''review-required:'' as the planner specified. A dedicated reviewer card is wired as your child and will claim once you block. Security constraints to obey: smart approval fail-closed by default; secrets via env reference not plaintext TOML; logs/status redact credentials and bound stdout/stderr; manual approval pending records must have stable id, lifecycle, timeout; no destructive remote commands in tests.', 1779697702);
