hen_create": true, "verification_findstr_Status": true, "extra_verify_lines": ["Run As User", "Schedule Type", "Task To Run", "Logon Mode"]}, "unregister_bat": {"schtasks_delete_tn_ssh_mcp_f": true, "no_error_if_task_missing": true}, "windows_autostart_md": {"why_task_scheduler_not_service_with_R1_section8_cite": true, "klist_verify_steps_with_purge_and_cmdkey_fallback": true, "coexistence_rule_RED_no_dual_launcher": true, "event_viewer_TaskScheduler_Operational_troubleshoot": true, "service_mode_for_non_kerberos_host_caveat": true}}, "lines": {"register_bat": 95, "unregister_bat": 37, "windows_autostart_md": 215}, "scope": "docs-only; WSL agent did not execute schtasks on Windows host", "skills_used": ["kanban-worker"], "post_write_fixes": ["Corrected /TR quoting from \\\"\\\"!LAUNCHER!\\\"\\\" to canonical \\\"!LAUNCHER!\\\" (single backslash-quote pair is the schtasks pattern for an embedded quoted path)."], "worker_session_id": "20260526_104425_a1b568"}', NULL);
