uests/store.ts", "../dbhub/src/utils/config-watcher.ts", "../dbhub/src/api/openapi.yaml", "../dbhub/dbhub.toml.example", "../dbhub/CLAUDE.md"], "key_findings": {"current_mcp_tools": ["exec", "sudo-exec", "list-servers"], "current_transport": "stdio only (StdioServerTransport)", "dbhub_config_search_paths": ["--config flag", "./dbhub.toml"], "dbhub_request_store_cap": 100, "ssh_mcp_test_gate_env": "SSH_MCP_DISABLE_MAIN=1"}, "recommendations_for_planner": ["Keep MCP on stdio only; WebUI is side-channel for status+approval (different threat model than dbhub SQL).", "Add llm.allow_egress boolean (default false) — prevents accidental command leak to OpenAI.", "Add llm.provider field for future Anthropic/Azure shapes.", "Boot-time fail when host != 127.0.0.1 AND auth_token empty (fail hard, not warn).", "Boot-time fail when approval.mode=manual AND webui.enabled=false.", "Hot-reload: re-key pending approvals by profile.id; deny if profile removed mid-reload.", "Audit fsync on append (or WAL); audit log is only forensic artifact.", "Static UI must render command/description via textContent, not innerHTML.", "Auto-promote --ssh=<JSON> into in-memory ResolvedSource so approval/audit pipeline is uniform."], "review_required": false, "worker_session_id": "20260525_162200_b11e31"}', NULL);
