INSERT OR IGNORE INTO 'task_runs'('id', 'task_id', 'profile', 'step_key', 'status', 'claim_lock', 'claim_expires', 'worker_pid', 'max_runtime_seconds', 'last_heartbeat_at', 'started_at', 'ended_at', 'outcome', 'summary', 'metadata', 'error') VALUES (10, 't_a3c8b5e1', 'researcher', NULL, 'done', NULL, NULL, NULL, 2700, NULL, 1779761669, 1779761884, 'completed', 'R1 research complete. Findings written to .hermes/research/2026-05-26_R1_http_transport_windows_kerberos.md covering: stdio-only confirmation at src/index.ts:524, SDK 1.29.0 StreamableHTTPServerTransport API + options (allowedHosts/allowedOrigins/enableDnsRebindingProtection/sessionIdGenerator), ssh2-no-GSSAPI confirmation, Windows in-box ssh.exe = SSPI/LSA (not MIT KfW), bearer-token+loopback+rebinding-guard recommendation, autostart via Task Scheduler interactive (NOT service), and labelled risk list. No code modified.', '{"artifacts": [".hermes/research/2026-05-26_R1_http_transport_windows_kerberos.md"], "sdk_version_installed": "1.29.0", "sdk_pin": "^1.17.5", "stdio_entry_point": "src/index.ts:522-538", "http_import_path": "@modelcontextprotocol/sdk/server/streamableHttp.js", "ssh2_gssapi_support": false, "windows_ssh_provider": "Microsoft in-box Win32-OpenSSH using SSPI (LSA cache)", "risks_red": ["audit-log secret leakage via command bodies", "multi-instance race between Windows-host and WSL via mirrored loopback"], "risks_yellow": ["WebUI auto-visible across mirrored loopback", "kerberos PreferredAuthentications=gssapi-with-mic disables fallback", "stateless mode adds per-call GSSAPI handshake latency"], "risks_green": ["SDK API stable in ^1.17.5 range", "openssh transport already plumbed for kerberos"], "recommended_env_vars": ["SSH_MCP_HTTP_TOKEN", "SSH_MCP_APPROVAL_LLM_URL", "SSH_MCP_APPROVAL_LLM_API_KEY", "SSH_MCP_APPROVAL_LLM_MODEL", "SSH_MCP_APPROVAL_LLM_CA_BUNDLE", "HTTPS_PROXY/HTTP_PROXY/NO_PROXY", "NODE_EXTRA_CA_CERTS"], "autostart_recommendation": "Task Scheduler ONLOGON /IT (interactive) — not a Windows Service; LocalSystem breaks Kerberos LSA", "worker_session_id": "20260526_101435_d531d6"}', NULL);
INSERT OR IGNORE INTO 'task_runs'('id', 'task_id', 'profile', 'step_key', 'status', 'claim_lock', 'claim_expires', 'worker_pid', 'max_runtime_seconds', 'last_heartbeat_at', 'started_at', 'ended_at', 'outcome', 'summary', 'metadata', 'error') VALUES (11, 't_00777089', 'planner', NULL, 'done', NULL, NULL, NULL, 2700, NULL, 1779761910, 1779762098, 'completed', 'P2 design complete. Plan saved at .hermes/plans/2026-05-26_P2_http-mcp-transport_windows-kerberos.md. Decision: Option B (in-process Streamable HTTP via SDK''s StreamableHTTPServerTransport), not the mcp-proxy bridge — keeps ssh-mcp in control of bearer/origin/rebinding/audit-transport semantics and lets stateful sessions reuse the warm ssh registry across Kerberos calls. Plan covers: file-level implementation map, [server.http] TOML schema with port 7022 default, CLI flag additions, defense-in-depth security stack, conditional PreferredAuthentications relax + Windows klist self-test (no MIT kinit fallback), 10 acceptance criteria, 8-row test matrix, and an explicit GREEN/YELLOW/RED list with two RED blockers (audit secret leakage, WSL+Windows multi-instance race) that developer-general must mitigate before merging. Handoff comment posted on child t_a60efb40 resolving the orchestrator''s Option-A-vs-B pre-comment.', '{"plan_path": ".hermes/plans/2026-05-26_P2_http-mcp-transport_windows-kerberos.md", "decision": "Option B in-process Streamable HTTP", "child_task": "t_a60efb40", "files_to_add": ["src/http-listener.ts", "src/audit/http-context.ts", "test/unit/http-transport.test.ts", "test/integration/http-handshake.test.ts", "test/unit/audit-transport-field.test.ts", "docs/deployment-windows.md"], "files_to_modify": ["src/index.ts (main(), parseArgv)", "src/config/toml.ts ([server.http] schema)", "src/audit/logger.ts (transport/remote_addr fields)", "src/transports/openssh.ts (relax PreferredAuthentications conditional + klist self-test)", "src/utils/shell.ts (extend sanitizePassword for Authorization headers)"], "toml_block": "[server.http] enabled/bind/port/auth_token_env/origin_allowlist/request_timeout_ms", "default_port": 7022, "green": ["StreamableHTTPServerTransport API stable in ^1.17.5 pin", "OpenSsh transport already routes kerberos correctly", "WSL mirrored loopback gives free reach to Windows host bind"], "yellow": ["WebUI auto-visible across mirrored loopback (single-user env, accepted)", "PreferredAuthentications relax only when fallback creds supplied", "No MIT kinit fallback path; document alt ssh.exe", "Stateful session memory cap LRU N=64"], "red": ["Audit log secret leakage: extend sanitizePassword to redact Authorization/Bearer before any audit row writes", "Multi-instance race WSL+Windows host on 127.0.0.1:7022: write runtime.json lock with {pid,bind,port,started_at}; fatal on collision"], "test_matrix_count": 8, "acceptance_criteria_count": 10, "worker_session_id": "20260526_101832_05fb57"}', NULL);
